"""Money parsing."""
from decimal import Decimal, InvalidOperation


def parse_amount(text):
    """Parse a ledger amount into a Decimal.

    Accepted forms, surrounding whitespace ignored:

    * plain or signed decimals: "12.50", "-12.50", "+12.50", "7"
    * thousands separators: "1,234.50"
    * accounting negatives in parentheses: "(12.50)" means -12.50

    The result always carries exactly two decimal places, so "7" parses to
    Decimal("7.00"). Anything else raises ValueError.
    """
    s = str(text).strip()
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()

    # A sign may directly precede a parenthesis, e.g. "(12.50)" or "(-12.50)".
    sign = ""
    if s[:1] in ("+", "-"):
        sign, s = s[0], s[1:]

    # Thousands separators: drop them, and require a digit to follow each one.
    if "," in s:
        if not all(len(part) == 3 for part in s.split(",")[1:]) or not s.replace(",", "").isdigit():
            raise ValueError(f"invalid amount: {text!r}")
        s = s.replace(",", "")
        if sign and negative:
            # A negative sign inside/around parentheses is redundant; keep one.
            pass
    else:
        if sign and not s:
            raise ValueError(f"invalid amount: {text!r}")

    body = s
    if not body:
        raise ValueError(f"invalid amount: {text!r}")
    # Allow an optional decimal point with at least one digit on each side.
    if "." in body:
        whole, _, frac = body.partition(".")
        if not whole.isdigit() or not frac.isdigit():
            raise ValueError(f"invalid amount: {text!r}")
    else:
        if not body.isdigit():
            raise ValueError(f"invalid amount: {text!r}")

    try:
        value = Decimal(body)
    except InvalidOperation:
        raise ValueError(f"invalid amount: {text!r}")

    if negative:
        value = -value
    if sign == "-":
        value = -value

    return value.quantize(Decimal("0.01"))

